package com.company.platform.aigateway.application;import com.company.platform.aigateway.infrastructure.TenantContextProvider;import java.sql.Timestamp;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;@Service public class AiGatewayService{private final JdbcTemplate jdbc;private final TenantContextProvider tenant;private final ProviderRegistry providers;private final ToolRegistry tools;private final PromptRegistry prompts;public AiGatewayService(JdbcTemplate j,TenantContextProvider t,ProviderRegistry p,ToolRegistry tr,PromptRegistry pr){jdbc=j;tenant=t;providers=p;tools=tr;prompts=pr;}private UUID t(){return tenant.currentTenantId();}public List<String> providers(){return providers.ids();}public List<Map<String,String>> tools(){return tools.list();}public List<Map<String,Object>> prompts(){return prompts.list();}public Map<String,Object> createSession(UUID user,Duration ttl){UUID id=UUID.randomUUID(),corr=UUID.randomUUID();Instant now=Instant.now();jdbc.update("INSERT INTO ai_session(id,tenant_id,correlation_id,user_id,created_at,expires_at,status) VALUES(?,?,?,?,?,?,?)",id,t(),corr,user,Timestamp.from(now),Timestamp.from(now.plus(ttl)),"ACTIVE");audit("SESSION_CREATE",null,null,null,id,corr);return Map.of("sessionId",id,"tenantId",t(),"correlationId",corr,"status","ACTIVE");}public List<Map<String,Object>> sessions(){return jdbc.queryForList("SELECT * FROM ai_session WHERE tenant_id=? ORDER BY created_at DESC",t());}public Map<String,Object> registerProvider(Map<String,Object>b){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO ai_provider(id,tenant_id,name,provider_type,version,status,created_at) VALUES(?,?,?,?,?,?,?)",id,t(),b.get("name"),b.get("providerType"),b.getOrDefault("version","v1"),"REGISTERED",Timestamp.from(Instant.now()));audit("PROVIDER_REGISTER",id,null,null,null,UUID.randomUUID());return Map.of("id",id,"tenantId",t(),"status","REGISTERED");}public Map<String,Object> registerTool(Map<String,Object>b){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO ai_tool(id,tenant_id,name,version,enabled,created_at) VALUES(?,?,?,?,?,?)",id,t(),b.get("name"),b.getOrDefault("version","v1"),false,Timestamp.from(Instant.now()));audit("TOOL_REGISTER",null,null,id,null,UUID.randomUUID());return Map.of("id",id,"tenantId",t(),"enabled",false);}public Map<String,Object> registerPrompt(Map<String,Object>b){UUID id=UUID.randomUUID();jdbc.update("INSERT INTO ai_prompt(id,tenant_id,key_name,version,classification,enabled,created_at) VALUES(?,?,?,?,?,?,?)",id,t(),b.get("key"),b.getOrDefault("version",1),b.getOrDefault("classification","internal"),false,Timestamp.from(Instant.now()));audit("PROMPT_REGISTER",null,id,null,null,UUID.randomUUID());return Map.of("id",id,"tenantId",t(),"enabled",false);}private void audit(String action,UUID provider,UUID prompt,UUID tool,UUID session,UUID corr){jdbc.update("INSERT INTO ai_audit(id,tenant_id,action,provider_id,prompt_id,tool_id,session_id,correlation_id,created_at) VALUES(?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),t(),action,provider,prompt,tool,session,corr,Timestamp.from(Instant.now()));}}
